import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        String input = reader.readLine();
        char[] data = input.toCharArray();
        int len = input.length();

        String[] suffixes = {"00", "25", "50", "75"};
        int answer = 0;

        if (data.length == 1) {
            if (data[0] == '0' || data[0] == 'X' || data[0] == '_') answer++;
        } else {
            for (String suffix : suffixes) {
                int fixedDigit = -1;
                int index = 0;
                boolean canForm = true;
                for (int i = len - 2; i < len; i++) {
                    char c = data[i];
                    char expected = suffix.charAt(index++);
                    if (c == '_') continue;
                    else if (c == 'X') {
                        if (fixedDigit == -1) fixedDigit = expected - '0';
                        else if (fixedDigit != expected - '0') {
                            canForm = false;
                            break;
                        }
                    } else if (c != expected) {
                        canForm = false;
                        break;
                    }
                }
                if (!canForm) continue;
                if (len == 2) {
                    if (suffix.charAt(0) == '0') continue;
                    answer++;
                    continue;
                }
                char[] tempData = Arrays.copyOf(data, len);
                int countX = 0;
                for (char c : data) if (c == 'X') countX++;
                if (fixedDigit != -1 || countX == 0) {
                    if (fixedDigit != -1) {
                        for (int k = 0; k < len; k++) {
                            if (data[k] == 'X') tempData[k] = (char) (fixedDigit + '0');
                        }
                    }
                    if (tempData[0] == '0') continue;
                    int ways = 1;
                    for (int k = 0; k < len - 2; k++) {
                        if (tempData[k] == '_') {
                            ways *= (k == 0) ? 9 : 10;
                        }
                    }
                    answer += ways;
                } else {
                    if (tempData[0] == '0') continue;
                    int ways = 1;
                    for (int k = 0; k < len - 2; k++) {
                        if (tempData[k] == '_') {
                            ways *= (k == 0) ? 9 : 10;
                        }
                    }
                    if (tempData[0] == 'X') {
                        ways *= 9;
                    } else {
                        ways *= 10;
                    }
                    answer += ways;
                }
            }
        }
        writer.println(answer);
        writer.close();
    }
}
